// Text is Unicode: bytes that are not UTF-8 are no Text, so not this type either.
[[nodiscard]] std::optional<model::Title> parse_title(std::string_view text) {
  if (!rt::unicode::is_valid_utf8(text)) {
    return std::nullopt;
  }
  return model::Title::make(std::string(text));
}

// A sum with no data is its variant names in lower case, exactly.
[[nodiscard]] std::optional<model::Priority> parse_priority(std::string_view text) {
  if (text == "low") {
    return model::Priority::Low;
  }
  if (text == "normal") {
    return model::Priority::Normal;
  }
  if (text == "high") {
    return model::Priority::High;
  }
  return std::nullopt;
}

// Text is Unicode: bytes that are not UTF-8 are no Text, so not this type either.
[[nodiscard]] std::optional<model::Tag> parse_tag(std::string_view text) {
  if (!rt::unicode::is_valid_utf8(text)) {
    return std::nullopt;
  }
  return model::Tag::make(std::string(text));
}

// ASCII digits only, one or more; leading zeros allowed. A value past 64 bits saturates: no store holds a number above 2^53, so it is in no world either.
[[nodiscard]] std::optional<model::TaskNo> parse_task_no(std::string_view text) {
  if (text.empty()) {
    return std::nullopt;
  }
  std::int64_t value = 0;
  for (const char c : text) {
    if (c < '0' || c > '9') {
      return std::nullopt;
    }
    const auto digit = static_cast<std::int64_t>(c - '0');
    value = value > (std::numeric_limits<std::int64_t>::max() - digit) / 10
                ? std::numeric_limits<std::int64_t>::max()
                : value * 10 + digit;
  }
  return model::TaskNo::make(value);
}

