std::optional<Value> Values::parse(ValueType type, std::string_view text) {
  switch (type) {
    case ValueType::Title:
      return rt::cli::as_value<Value>(parse_title(text));
    case ValueType::Priority:
      return rt::cli::as_value<Value>(parse_priority(text));
    case ValueType::Tag:
      return rt::cli::as_value<Value>(parse_tag(text));
    case ValueType::TaskNo:
      return rt::cli::as_value<Value>(parse_task_no(text));
  }
  std::unreachable();
}

